#pragma once

// Immutable manufacturing facts stored with a JusPrin project: builds,
// exported copies, and the physical-print ledger.

#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

struct SliceStatistics
{
    double        print_time_seconds{0.0};
    double        filament_mm{0.0};
    double        material_grams{0.0};
    double        material_cost{0.0};
    std::uint64_t layer_count{0};
};

struct BuildRecord
{
    std::string   id;
    std::uint64_t seq{0};
    std::string   created_at;
    std::string   project_id;
    std::string   conversation_id;
    std::string   after_message_id;
    std::size_t   plate_index{0};
    std::string   plate_name;
    std::string   printer;
    std::string   material;
    std::string   manufacturing_input_hash;
    std::string   output_hash;
    std::string   slicer_version;
    std::string   configuration_provenance;
    // Present only after a printer transfer is confirmed. A build alone does
    // not imply that its G-code was sent to a machine.
    std::string   sent_at;
    std::string   delivery_confirmed_at;
    std::string   delivery_location;
    SliceStatistics statistics;
    std::vector<std::string> warnings;
};

struct ExportedCopyRecord
{
    std::string   id;
    std::uint64_t seq{0};
    std::string   created_at;
    std::string   build_id;
    std::string   conversation_id;
    std::string   after_message_id;
    std::string   destination;
    std::string   expected_output_hash;
    // Optional checksum observed at the destination. Whether the copy matches
    // is always derived from the two hashes; no mutable "modified" flag is
    // persisted.
    std::string observed_output_hash;
};

struct PhysicalPrintRecord
{
    std::string   id;
    std::uint64_t seq{0};
    std::string   started_at;
    std::string   ended_at;
    std::string   outcome; // completed|failed|cancelled
    std::string   failure;
    std::string   build_id;
    std::string   project_id;
    std::string   conversation_id;
    std::string   after_message_id;
    std::size_t   plate_index{0};
    std::string   plate_name;
    std::string   printer;
    std::string   material;
    std::string   manufacturing_input_hash;
    std::string   output_hash;
    std::string   gcode_hash;
    std::optional<int> stopped_percent;
    SliceStatistics statistics;
};

// Stable lowercase SHA-256 for persisted provenance.
std::string sha256_hex(const std::string& bytes);

// Canonical hash of the manufacturing facts exposed by IWorkspace for one
// plate. It deliberately excludes selection, undo state, dirty state, object
// names, and the process-local project session. A missing plate has no hash.
std::optional<std::string> manufacturing_input_hash(const Workspace::WorkspaceSnapshot& snapshot,
                                                    std::size_t                         plate_index);

// Deterministic G-code identity used by the typed Phase Six record workflow.
// A production slicer adapter may replace the source bytes, but the persisted
// contract remains an immutable SHA-256 string.
std::string deterministic_output_hash(const std::string& manufacturing_hash,
                                      const std::string& slicer_version,
                                      const std::string& configuration_provenance);

} // namespace Slic3r::GUI::JusPrin::Agent
    // Removes a staged attachment record; returns its relative_dir for blob
    // cleanup, or nullopt when it does not exist or is not staged.
    std::optional<std::string> remove_staged_attachment(const std::string& attachment_id);
    // Flips the given staged attachments to "sent". IDs that are missing or
    // not staged are ignored; returns the IDs that were actually sent.
    std::vector<std::string> mark_attachments_sent(const std::vector<std::string>& attachment_ids);

    // -- Manufacturing history --------------------------------------------
    // Add-only immutable records.
    std::string add_build(BuildRecord record, const std::string& timestamp);
    std::string add_exported_copy(ExportedCopyRecord record, const std::string& timestamp);
    std::string add_physical_print(PhysicalPrintRecord record, const std::string& timestamp);
    std::vector<BuildRecord>         builds() const;
    std::vector<ExportedCopyRecord>  exported_copies() const;
    std::vector<PhysicalPrintRecord> physical_prints() const;
    // Ledger size without materializing every record; the shell's status row
    // reads this on every project change.
    std::size_t                      physical_print_count() const;
    std::optional<BuildRecord>       find_build(const std::string& build_id) const;
    std::optional<BuildRecord>       latest_build() const;

    // -- Print intent and plan ------------------------------------------------
    // Product state with no Orca owner: it travels in the project archive
    // because it describes this print, and it is not in Orca's undo stack.
    std::vector<IntentField> print_intent() const; // ordered by field name
    // Upserts by field name and returns the fields as stored. A field the call
    // does not mention keeps the value, provenance, and seq it had.
    std::vector<IntentField> set_print_intent(const std::vector<IntentField>& fields, const std::string& timestamp);
    // The pinned plan, or a default record when the agent has not written one.
    PlanRecord plan() const;
    // Replaces the plan wholesale: it is one statement, not a list of edits.
    PlanRecord set_plan(PlanRecord record, const std::string& timestamp);
    // Region annotations. The list is replaced whole; a record with no seq is
    // new or changed and is stamped on the way in.
    std::vector<Workspace::RegionRecord> regions() const;
    std::vector<Workspace::RegionRecord> set_regions(std::vector<Workspace::RegionRecord> records, const std::string& timestamp);
    // Version restore keeps the current conversation and manufacturing audit
    // while taking the earlier version's project-specific intent and plan.

    // -- Change log -----------------------------------------------------------
    // Appends with the next seq, placed in the active conversation after its
    // most recent item. Returns the entry as stored.
    ChangeEntry              add_change(ChangeEntry entry, const std::string& timestamp);
    std::vector<ChangeEntry> changes() const;
    // The conversation's most recent message or tool activity, by seq; empty
    // when it has none.
    std::string last_item_id(const std::string& conversation_id) const;

    // Raw access for tests and serialization helpers.
    const nlohmann::json& raw() const { return m_doc; }

    std::vector<BuildRecord> result;
    for (const json& entry : m_doc["builds"])
        result.push_back(read_build(entry));
    return result;
}

std::vector<ExportedCopyRecord> ProjectStateDocument::exported_copies() const
{
    std::vector<ExportedCopyRecord> result;
    for (const json& entry : m_doc["exportedCopies"])
        result.push_back(read_exported_copy(entry));
    return result;
}

std::vector<PhysicalPrintRecord> ProjectStateDocument::physical_prints() const
{
    std::vector<PhysicalPrintRecord> result;
    for (const json& entry : m_doc["physicalPrints"])
        result.push_back(read_physical_print(entry));
    return result;
}

std::size_t ProjectStateDocument::physical_print_count() const
{
    return m_doc["physicalPrints"].size();
}

std::optional<BuildRecord> ProjectStateDocument::find_build(const std::string& build_id) const
{
    for (const json& entry : m_doc["builds"])
        if (entry.value("id", "") == build_id)
            return read_build(entry);
    return std::nullopt;
}

std::optional<BuildRecord> ProjectStateDocument::latest_build() const
{
    if (m_doc["builds"].empty())
        return std::nullopt;
    return read_build(m_doc["builds"].back());
}

std::vector<IntentField> ProjectStateDocument::print_intent() const
{
    std::vector<IntentField> fields;
    for (const json& entry : m_doc["printIntent"])
        fields.push_back(read_intent_field(entry));
    return fields;
}

std::vector<IntentField> ProjectStateDocument::set_print_intent(const std::vector<IntentField>& fields,

