    }
    void process(Ctl& ctl) override { m_inner->process(ctl); }
    void finalize(bool canceled, std::exception_ptr& eptr) override
    {
        m_inner->finalize(canceled, eptr);
        m_reported = true;
        m_done(canceled ? "cancelled" : eptr ? "failed" : "finished");
    }

